src='''def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    for r in range(h):
        for c in range(w):
            if (r, c) in seen:
                continue
            color = grid[r][c]
            comp = set()
            stack = [(r, c)]
            seen.add((r, c))
            while stack:
                y, x = stack.pop()
                comp.add((y, x))
                for yy, xx in ((y - 1, x), (y + 1, x), (y, x - 1), (y, x + 1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy, xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy, xx))
                        stack.append((yy, xx))
            ys = [y for y, x in comp]
            xs = [x for y, x in comp]
            y0, y1, x0, x1 = min(ys), max(ys), min(xs), max(xs)
            bh, bw = y1 - y0 + 1, x1 - x0 + 1
            if bh < 3 or bw < 3:
                continue
            perimeter = {(y0, x) for x in range(x0, x1 + 1)} | {(y1, x) for x in range(x0, x1 + 1)} | {(y, x0) for y in range(y0, y1 + 1)} | {(y, x1) for y in range(y0, y1 + 1)}
            if comp == perimeter:
                ih, iw = bh - 2, bw - 2
                fill = 2 if ih % 2 == 0 and iw % 2 == 0 else 7
                for y in range(y0 + 1, y1):
                    for x in range(x0 + 1, x1):
                        out[y][x] = fill
    return out
'''
